PLAN = {
    "schema_version": 1,
    "default_context_refs": [PREFLIGHT, f"{A}#ctx.project-summary.001", "brief.hq-shared-foundation#iface.shell.001",
                             "brief.hq-shared-foundation#iface.references.001"],
    "deferred_findings_sink_ref": "worknote.hq-social-work#ctx.deferred-findings.001",
    "artifact_path_hints": {A: "docs/engineering-specs/hq-social-work.md",
                            "brief.hq-shared-foundation": "docs/design/hq-shared-foundation.md",
                            "worknote.hq-social-work": "docs/work-notes/hq-social-work.md"},
    "launch_policy": "start_all_currently_launchable_with_rolling_capacity_refill",
    "machine_block_source_rendering": "deterministic_two_space_json",
    "runtime_rendering": "canonical_compact_json",
    "fan_in_owner": "hq-root",
    "additional_final_check_groups": ["hq-foundation", "shell-integration"],
    "delivery_boundary": "Root launches lanes from this published plan on the accepted T0 base; lanes publish candidate PRs; merge held for integration-owner agreement; no deployment, signing, service change, migration or live-data access; tests/check-groups.toml stays with its Design owner.",
}

def block(ref, value):
    return f'<!-- codex-section:begin id="{ref}" -->\n```json\n{render_authored_json(value)}```\n<!-- codex-section:end id="{ref}" -->\n'

out = [block(f"{A}#plan.implementation.001", PLAN)]
out += [block(ref, v) for ref, v in TASKS]
out += [block(ref, v) for ref, v in INTENTS]
path = sys.argv[1]
s = open(path).read()
if "@@MACHINE_BLOCKS@@\n" in s:
    s = s.replace("@@MACHINE_BLOCKS@@\n", "".join(out[:1]) + "\n" + "\n".join(out[1:]))
else:  # regenerate in place: plan block through the last Test Intent block
    start = s.index(f'<!-- codex-section:begin id="{A}#plan.implementation.001" -->')
    ends = [m.end() for m in re.finditer(rf'<!-- codex-section:end id="{re.escape(A)}#test\.[a-z0-9-]+\.001" -->\n', s)]
    s = s[:start] + "".join(out[:1]) + "\n" + "\n".join(out[1:]) + s[ends[-1]:]
open(path, "w").write(s)
print(len(TASKS), "tasks", len(INTENTS), "intents")
